INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Netzwerktechnik immer Daten verschlüsselt?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird oft verwendet, um Daten durch ein anderes Netzwerk zu leiten?', 3, '[{"text": "IPsec", "correct": true, "because": "Sichert Tunnel"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Technik zur Datenübertragung?', 5, '[{"text": "Verkapselung", "correct": true, "because": "Pakete in Paketen"}, {"text": "Sicherheit", "correct": true, "because": "Oft verschlüsselt"}, {"text": "Punkt-zu-Punkt", "correct": true, "because": "Verbindet Endpunkte"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) VPN nutzt diese Technik. b) Sie ist immer unsicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicher mit Protokollen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine sichere Verbindung einrichte?', 4, '[{"text": "Verschlüsselung", "correct": false, "because": "Schützt Daten"}, {"text": "Endpunkte", "correct": false, "because": "Definiert Tunnel"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine solche Technik nur für lokale Netzwerke ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch über Internet"}, {"text": "Ja", "correct": false, "because": "Global nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll verkapselt Daten für sichere Übertragung?', 3, '[{"text": "GRE", "correct": true, "because": "General Routing Encapsulation"}, {"text": "DNS", "correct": false, "because": "Namensauflösung"}, {"text": "SMTP", "correct": false, "because": "E-Mail"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Technik zur Datenleitung?', 5, '[{"text": "Sicherheit", "correct": true, "because": "Durch Verschlüsselung"}, {"text": "Flexibilität", "correct": true, "because": "Über Netzwerke hinweg"}, {"text": "Privatsphäre", "correct": true, "because": "Versteckt Daten"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) IPsec verschlüsselt und b) GRE immer unsicher ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GRE kann mit IPsec sicher sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Netzwerkverbindung aufzubauen?', 4, '[{"text": "Endpunkte", "correct": false, "because": "Definieren Tunnel"}, {"text": "Protokoll", "correct": false, "because": "Leitet Daten"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine solche Technik immer verschlüsselt?', 2, '[{"text": "Nein", "correct": true, "because": "Z. B. GRE ohne IPsec"}, {"text": "Ja", "correct": false, "because": "Optional sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle unterstützen sichere Datenübertragung?', 4, '[{"text": "IPsec", "correct": true, "because": "Verschlüsselt Tunnel"}, {"text": "PPTP", "correct": true, "because": "Point-to-Point Tunneling"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine solche Technik nur für IPv4 ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv6 unterstützt"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Netzwerkverbindungstechnik?', 3, '[{"text": "Sichere Kommunikation", "correct": true, "because": "Schützt Daten"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) VPN nutzt Verkapselung. b) Es ist immer langsam.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt IPsec?', 4, '[{"text": "Daten verschlüsseln", "correct": true, "because": "Sichert Tunnel"}, {"text": "Daten anzeigen", "correct": false, "because": "Kein Zweck"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine solche Technik immer einen Server braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Punkt-zu-Punkt möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Netzwerkverbindungstechnik nützlich?', 5, '[{"text": "Sicherheit", "correct": true, "because": "Schützt Daten"}, {"text": "Flexibilität", "correct": true, "because": "Über Netzwerke hinweg"}, {"text": "Vertraulichkeit", "correct": true, "because": "Versteckt Pakete"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt GRE immer Verschlüsselung?', 3, '[{"text": "Nein", "correct": true, "because": "Nur mit IPsec sicher"}, {"text": "Ja", "correct": false, "because": "Optional verschlüsselt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer Netzwerkverbindungstechnik?', 4, '[{"text": "VPN zwischen Büros", "correct": true, "because": "Sichere Verbindung"}, {"text": "Webseitenhosting", "correct": false, "because": "Anderer Zweck"}, {"text": "Datenkompression", "correct": false, "because": "Sekundär"}]');
